const modes:{id:AppearanceMode;label:string;caption:string}[]=[{id:'light',label:'浅色',caption:'明亮 · 轻盈'},{id:'dark',label:'深色',caption:'沉静 · 专注'},{id:'system',label:'跟随系统',caption:'随设备自动切换'}];
function setMode(mode:AppearanceMode){emit('update:modelValue',{...props.modelValue,mode});}
</script>
