 <view class="appearance-settings">
  <view class="appearance-heading"><view><text class="appearance-title">外观</text><text class="appearance-description">让界面，更合你的喜好</text></view><text class="appearance-badge">{{scheme==='dark'?'深色模式':'浅色模式'}}</text></view>
  <view class="scheme-options" role="group" aria-label="界面模式">
   <button v-for="mode in modes" :key="mode.id" class="scheme-option" :class="{selected:modelValue.mode===mode.id}" :aria-pressed="modelValue.mode===mode.id" @click="setMode(mode.id)">
    <view class="scheme-preview" :class="'preview-'+mode.id" aria-hidden="true"><view class="mini-sidebar"><view/><view/><view/></view><view class="mini-content"><view class="mini-header"/><view class="mini-feature"/><view class="mini-cards"><view/><view/><view/></view></view><view class="scheme-check">✓</view></view>
    <text class="scheme-label">{{mode.label}}</text><text class="scheme-caption">{{mode.caption}}</text>
   </button>
  </view>
  <view class="accent-heading"><text>主题色</text><text>仅改变重点色彩</text></view>
  <view class="accent-options" role="group" aria-label="主题色">
   <button v-for="accent in appearanceAccents" :key="accent.id" class="accent-option" :class="{selected:modelValue.accent===accent.id}" :aria-label="accent.label" :aria-pressed="modelValue.accent===accent.id" @click="emit('update:modelValue',{...modelValue,accent:accent.id})"><view class="accent-swatch" :style="{background:scheme==='dark'?accent.dark:accent.light,color:scheme==='dark'?'#111318':'#ffffff'}"><text v-if="modelValue.accent===accent.id">✓</text></view><text>{{accent.label}}</text></button>
  </view>
  <text class="appearance-footnote" :class="{warning:error}" aria-live="polite">{{error||'即时生效，自动保存到本机'}}</text>
 </view>
